//! The host page's code is generated by Rust at every Build (WASM-002 Q6, plan §4.1): every file the
//! Build writes for the page starts with the banner, two Builds of the same input give the same bytes,
//! and the crate keeps no JavaScript, HTML or CSS source of its own.

mod support;

use cobolt_web_bundle::hostpage::{
    BANNER_CSS, BANNER_HTML, BANNER_JS, DECLARED_BROWSERS, WORKERS_CAP,
};
use cobolt_web_bundle::{BundleOptions, BundleOutput, PlayerInput, PlayerVariantInput};

/// A stand-in player: the assembler copies the player's files and does not read them.
fn player() -> PlayerInput {
    let plain = PlayerVariantInput {
        files: vec![
            (
                "player.js".into(),
                b"export default async function init() {}\n".to_vec(),
            ),
            ("player_bg.wasm".into(), b"\0asm\x01\0\0\0".to_vec()),
        ],
        entry_js: "player.js".into(),
        entry_wasm: "player_bg.wasm".into(),
    };
    PlayerInput {
        plain: Some(plain),
        ..Default::default()
    }
}

fn build() -> BundleOutput {
    support::assemble(
        player(),
        BundleOptions {
            service_worker_shim: true,
            style: cobolt_web_bundle::AppStyle::Standalone,
            ..Default::default()
        },
    )
}

#[test]
fn every_page_script_and_stylesheet_starts_with_the_banner() {
    let out = build();
    let mut checked = Vec::new();
    for f in out.files.iter().filter(|f| !f.path.starts_with("player/")) {
        let banner = if f.path.ends_with(".js") {
            BANNER_JS
        } else if f.path.ends_with(".html") {
            BANNER_HTML
        } else if f.path.starts_with("app.") && f.path.ends_with(".css") {
            BANNER_CSS
        } else {
            continue;
        };
        let text = String::from_utf8_lossy(&f.bytes);
        assert!(
            text.starts_with(banner),
            "{} does not start with the banner",
            f.path
        );
        assert!(
            !text.contains("{{") && !text.contains("__LOADER__"),
            "{}: a placeholder was left in",
            f.path
        );
        checked.push(f.path.clone());
    }
    println!("banner on {} files: {checked:?}", checked.len());
    // loader, worker, app, the shim and its registration, app.css, index.html and one page per form.
    let forms = out.config()["forms"].as_array().unwrap().len();
    assert_eq!(checked.len(), 6 + 1 + forms, "{checked:?}");

    let loader = out
        .files
        .iter()
        .find(|f| f.path.starts_with("loader."))
        .unwrap();
    let loader = String::from_utf8_lossy(&loader.bytes);
    assert!(
        loader.contains(DECLARED_BROWSERS),
        "the R15 message names the declared matrix"
    );
    assert!(
        loader.contains(&format!(
            "Math.min({WORKERS_CAP}, p.hardwareConcurrency - 1)"
        )),
        "the Worker default is written in"
    );
    let app = out
        .files
        .iter()
        .find(|f| f.path.starts_with("app.") && f.path.ends_with(".js"))
        .unwrap();
    let app = String::from_utf8_lossy(&app.bytes);
    assert!(
        app.contains(&format!(
            "from './{}'",
            out.files
                .iter()
                .find(|f| f.path.starts_with("loader."))
                .unwrap()
                .path
        )),
        "app.js imports the hashed loader"
    );
}

#[test]
fn two_builds_of_the_same_input_are_byte_identical() {
    let (a, b) = (build(), build());
    assert_eq!(a.files.len(), b.files.len());
    for (x, y) in a.files.iter().zip(&b.files) {
        assert_eq!(x.path, y.path);
        assert!(x.bytes == y.bytes, "{} differs between two builds", x.path);
    }
    println!("{} files, identical across two builds", a.files.len());
}

#[test]
fn the_crate_keeps_no_javascript_html_or_css_source() {
    fn walk(dir: &std::path::Path, out: &mut Vec<String>) {
        for e in std::fs::read_dir(dir).unwrap().flatten() {
            let p = e.path();
            if p.is_dir() {
                walk(&p, out);
            } else if matches!(
                p.extension().and_then(|e| e.to_str()),
                Some("js" | "mjs" | "html" | "htm" | "css")
            ) {
                out.push(p.display().to_string());
            }
        }
    }
    let mut found = Vec::new();
    walk(std::path::Path::new(env!("CARGO_MANIFEST_DIR")), &mut found);
    assert!(
        found.is_empty(),
        "non-Rust host-page source is back in the crate: {found:?}"
    );
}
